namespace ghidra.framework.client;

using static org.junit.Assert;










using org.junit;
using org.junit.experimental.categories;

using generic.test.category;
using ghidra.framework.model;
using ghidra.framework.remote;
using ghidra.net;
using ghidra.server.remote;
using ghidra.test;
using ghidra.util.task;
using utilities.util;

/* @Category(typeof(PortSensitiveCategory)) */
public class GhidraServerSerialFilterFailureTest : AbstractGhidraHeadlessIntegrationTest {

	private File serverRoot;

	/* @Before */
	public void setUp()
    {
		System.clearProperty(DefaultKeyManagerFactory.KEYSTORE_PATH_PROPERTY);
	}

	/* @After */
	public void tearDown()
    {
		closeAllWindows();
		killServer();

		ClientUtil.clearRepositoryAdapter("localhost", ServerTestUtil.GHIDRA_TEST_SERVER_PORT);
	}

	private void killServer() {

		if (serverRoot == null) {
			return;
		}

		ServerTestUtil.disposeServer();

		FileUtilities.deleteDir(serverRoot);
	}

	private void startServer(int authMode, bool altLoginName, bool enableSSH,
			bool enableAnonymous)
    {

		// Create server instance
		serverRoot = new File(getTestDirectoryPath(), "TestServer");

		ServerTestUtil.startServer(serverRoot.getAbsolutePath(),
			ServerTestUtil.GHIDRA_TEST_SERVER_PORT, authMode, altLoginName, enableSSH,
			enableAnonymous);
	}

	static class BogusPrincipal : Principal, java.io.Serializable {

		private string username;

		public BogusPrincipal(string username) {
			this.username = username;
		}

		/* @Override */
		public string getName() {
			return username;
		}
	}

	private static Subject getBogusUserSubject() {
		string username = ClientUtil.getUserName();
		HashSet<BogusPrincipal> pset = new();
		HashSet<object> emptySet = new();
		pset.add(new BogusPrincipal(username));
		Subject subj = new Subject(false, pset, emptySet, emptySet);
		return subj;
	}

	/* @Test */
	public void testSerializationFailure()
    {

		ServerTestUtil.setLocalUser("test");
		startServer(-1, false, false, false);

		ServerInfo server = new ServerInfo("localhost", ServerTestUtil.GHIDRA_TEST_SERVER_PORT);

		GhidraServerHandle serverHandle =
			ServerConnectTask.getGhidraServerHandle(server, TaskMonitor.DUMMY);

		try {
			serverHandle.getRepositoryServer(getBogusUserSubject(), new Callback[0]);
			fail("serial filter rejection failed to perform");
		}
		catch (Exception e) {
			Throwable cause = e.getCause();
			assertTrue("Expected remote unmarshall exception", e is UnmarshalException);
			assertTrue("Expected remote invalid class exceptionn",
				cause is InvalidClassException);
		}

	}

}
